mapper.update:
UPDATE time_capsule_entry
SET media_mode = #{mediaMode}
WHERE time_capsule_entry_id = #{timeCapsuleEntryId}
  AND status = 'DRAFT'
  AND media_mode = 'NONE'

mapper.select:
SELECT COUNT(*)
FROM time_capsule_media
WHERE time_capsule_entry_id = #{timeCapsuleEntryId}
  AND status = 'ACTIVE'
  AND media_type = #{mediaType}
